// SPL2ParserInit initializes any static state used to implement SPL2Parser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewSPL2Parser(). You can call this function if you wish to initialize the static state ahead
// of time.
func SPL2ParserInit() {
	staticData := &SPL2ParserParserStaticData
	staticData.once.Do(spl2parserParserInit)
}

// NewSPL2Parser produces a new parser instance for the optional input antlr.TokenStream.
func NewSPL2Parser(input antlr.TokenStream) *SPL2Parser {
	SPL2ParserInit()
	this := new(SPL2Parser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &SPL2ParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "SPL2Parser.g4"

	return this
}

// Note that '@members' cannot be changed now, but this should have been 'globals'
// If you are looking to have variables for each instance, use '@structmembers'

// Casing is recognized only in an operator grammar position. The same lower-
// case token remains an ordinary identifier or search literal elsewhere.
func (p *SPL2Parser) extendedUnknownOption() bool {
	token := p.GetTokenStream().LA(1)
	for ctx := p.GetParserRuleContext(); ctx != nil; {
		var known []int
		switch ctx.(type) {
		case *RexCommandContext:
			known = []int{SPL2ParserFIELD, SPL2ParserMAX_MATCH, SPL2ParserOFFSET_FIELD, SPL2ParserMODE}
		case *AppendpipeCommandContext:
			known = []int{SPL2ParserRUN_IN_PREVIEW}
		case *BinCommandContext:
			known = []int{SPL2ParserBINS, SPL2ParserMINSPAN, SPL2ParserSPAN, SPL2ParserSTART, SPL2ParserEND, SPL2ParserALIGNTIME}
		case *SpathCommandContext:
			known = []int{SPL2ParserINPUT, SPL2ParserPATH, SPL2ParserOUTPUT_LOWER}
		case *MakemvCommandContext:
			known = []int{SPL2ParserDELIM, SPL2ParserTOKENIZER}
		case *MvexpandCommandContext:
			known = []int{SPL2ParserLIMIT}
		case *MvcombineCommandContext:
			known = []int{SPL2ParserDELIM}
		case *FillnullCommandContext:
			known = []int{SPL2ParserVALUE}
		case *MetricsCommandContext:
			known = []int{SPL2ParserAGGREGATES, SPL2ParserPREDICATE, SPL2ParserBYFIELDS, SPL2ParserDATAMODEL_NAME}
		case *TimechartCommandContext:
			known = []int{SPL2ParserBINS, SPL2ParserMINSPAN, SPL2ParserSPAN, SPL2ParserSTART, SPL2ParserEND, SPL2ParserALIGNTIME, SPL2ParserSEP, SPL2ParserFORMAT, SPL2ParserPARTIAL, SPL2ParserCONT, SPL2ParserFIXEDRANGE, SPL2ParserLIMIT, SPL2ParserAGG, SPL2ParserUSENULL, SPL2ParserUSEOTHER, SPL2ParserNULLSTR, SPL2ParserOTHERSTR}
		}
		if known != nil {
			for _, k := range known {
				if k == token {
					return false
				}
			}
			return true
		}
		parent, _ := ctx.GetParent().(antlr.ParserRuleContext)
		ctx = parent
	}
	return true
}
func (p *SPL2Parser) adjacentPrevious() bool {
	return p.GetTokenStream().LT(-1).GetStop()+1 == p.GetTokenStream().LT(1).GetStart()
}
func (p *SPL2Parser) contextualKeyword(word string) bool {
	return strings.EqualFold(p.GetTokenStream().LT(1).GetText(), word)
}

// SQL clause words remain ordinary identifiers in previously supported pipeline
// expressions. Within SQL they are boundaries, not missing operand fallbacks.
func (p *SPL2Parser) outsideSQL() bool {
	for ctx := p.GetParserRuleContext(); ctx != nil; {
		switch ctx.(type) {
		case *FromCommandContext, *SelectCommandContext:
			return false
		}
		parent, _ := ctx.GetParent().(antlr.ParserRuleContext)
		ctx = parent
	}
	return true
}

// Supported options must use their owning command's strict production. Tokens
// documented for other commands remain typed, unproved options here.
func (p *SPL2Parser) unreviewedOption(command int) bool {
	token := p.GetTokenStream().LA(1)
	switch command {
	case SPL2ParserSTATS:
		return token != SPL2ParserBY && token != SPL2ParserALLNUM && token != SPL2ParserDELIM && token != SPL2ParserPARTITIONS
	case SPL2ParserEVENTSTATS:
		return token != SPL2ParserBY && token != SPL2ParserALLNUM
	case SPL2ParserSTREAMSTATS:
		return token != SPL2ParserBY && token != SPL2ParserCURRENT && token != SPL2ParserRESET && token != SPL2ParserWINDOW
	case SPL2ParserDEDUP:
		return token != SPL2ParserKEEPEMPTY && token != SPL2ParserCONSECUTIVE
	case SPL2ParserHEAD:
		return token != SPL2ParserKEEPLAST && token != SPL2ParserWHILE
	}
	return true
}

